var t=`0298-tave-kosi`;var n=`world-0298`;var a=`AL`;var l=`southern-europe`;var r=4;var s=78;var o={en:`Tavë Kosi`,ua:`Таве косі`};var g={en:`A traditional Albania dish made with lamb shoulder, plain yogurt, chicken egg, white rice. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Албанія. Основні інгредієнти: лопатка ягняти, натуральний йогурт, куряче яйце, білий рис. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var d=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 13 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 13 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:13,i:[[`lamb-shoulder`,700,`g`],[`extra-virgin-olive-oil`,45,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:7,i:[[`plain-yogurt`,500,`g`],[`chicken-egg`,3,`pcs`],[`white-rice`,85,`g`],[`all-purpose-flour`,40,`g`],[`garlic`,2,`clove`]]},{en:`Layer the prepared elements evenly in the baking dish, spreading filling right to the edges.`,ua:`Викладіть підготовлені компоненти рівними шарами у формі, розподіляючи начинку до країв.`,t:[`layered-assembly`],m:5,i:[]},{en:`Bake the lamb-and-yogurt casserole at 180°C until bubbling and the custard is fully set and lightly golden; allow it to rest briefly.`,ua:`Запікайте ягнячо-йогуртову запіканку при 180°C до легкого рум’янцю та повного схоплення заливки; дайте їй недовго постояти.`,t:[`baking`],m:53,i:[[`unsalted-butter`,50,`g`]]}];var u={slug:t,id:n,country:`AL`,region:l,servings:4,minutes:78,title:o,text:g,steps:d};export{a as country,u as default,n as id,s as minutes,l as region,r as servings,t as slug,d as steps,g as text,o as title};